css:
.tpl-hf-typewriter-phrase { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 8%; background: linear-gradient(135deg, #1b2424 0%, #0b2328 48%, #182b18 100%); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-hf-typewriter-phrase .kicker { font-size: clamp(14px, 2vmin, 24px); font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; color: var(--accent, #32fff6); margin-bottom: clamp(14px, 3vh, 32px); opacity: 0; }
.tpl-hf-typewriter-phrase .phrase-stage { text-align: center; font-size: clamp(32px, 6.8vmin, 92px); font-weight: 800; line-height: 1.28; letter-spacing: -0.02em; max-width: 1460px; }
.tpl-hf-typewriter-phrase .phrase-main { color: var(--fg, #ffffff); white-space: pre-wrap; }
.tpl-hf-typewriter-phrase .phrase-accent { color: var(--accent, #32fff6); text-shadow: 0 0 36px rgba(50,255,246,0.35); white-space: pre-wrap; }
.tpl-hf-typewriter-phrase .phrase-cursor { display: inline-block; width: 0.42em; height: 0.88em; margin-left: 0.12em; vertical-align: -0.08em; background: #ffffff; border-radius: 3px; }
